('df316388-caf3-5ffb-a632-a947ad8ff417','384f69f0-1a3c-536d-b8f2-ecef5fcb3d6e',1,'noun','A2','S1','W1',null,'[{"phrase":"take care","register":"spoken","definition_en":"used when saying goodbye to family and friends","translation":"هنگام خداحافظی با خانواده و دوستان استفاده می شود","example":"Take care! See you next week!","example_translation":"مراقب باشید! هفته آینده می بینمت!","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001666527.mp3"},{"phrase":"care of somebody","register":null,"definition_en":"used when sending letters to someone at someone else’s address","translation":"هنگام ارسال نامه به شخصی به آدرس شخص دیگری استفاده می شود","example":"Send me the letter care of my uncle.","example_translation":"نامه مراقبت از عمویم را برای من بفرست.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001666557.mp3"}]'::jsonb),
('01cc4f7a-7c24-5693-af75-a97c42db8c60','384f69f0-1a3c-536d-b8f2-ecef5fcb3d6e',2,'verb','A2','S1','W2','[ intransitive, transitive ]','[{"phrase":"who cares?","register":"spoken","definition_en":"used to say that something does not worry or upset you because it is not important","translation":"معمولاً می گفت چیزی شما را نگران یا ناراحت نمی کند زیرا مهم نیست","example":"It’s rather old and scruffy, but who cares?","example_translation":"نسبتاً قدیمی و شلخته است، اما چه کسی اهمیت می دهد؟","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001056151.mp3"},{"phrase":"what does somebody care?","register":"spoken","definition_en":"used to say that someone does not care at all about something","translation":"می گفت کسی اصلاً به چیزی اهمیت نمی دهد","example":"What do I care? It’s your responsibility now!","example_translation":"من چه اهمیتی دارم؟ اکنون مسئولیت شماست!","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001056165.mp3"},{"phrase":"for all somebody cares","register":"spoken","definition_en":"used when you are angry that someone does not seem concerned about someone or something","translation":"وقتی عصبانی هستید که به نظر می رسد کسی نگران کسی یا چیزی نیست، استفاده می شود","example":"We could be starving for all they care!","example_translation":"ما ممکن است به خاطر همه چیزهایی که آنها اهمیت می دهند گرسنه باشیم!","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001056179.mp3"},{"phrase":"not care to do something","register":"old-fashioned","definition_en":"to not like doing something","translation":"دوست نداشتن کاری","example":"She doesn’t care to spend much time with her relatives.","example_translation":"او اهمیتی نمی دهد که زمان زیادی را با اقوامش بگذراند.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001056186.mp3"}]'::jsonb),
